SELECT a.id, b.id FROM a LEFT JOIN b ON a.id = b.id
UNION
SELECT a.id, b.id FROM a RIGHT JOIN b ON a.id = b.id;

SELECT e.name AS employee, m.name AS manager
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.id;

SELECT c.name FROM customers c
WHERE EXISTS (
    SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.amount > 1000
);

SELECT avg_dept_sal FROM (
    SELECT department, AVG(salary) AS avg_dept_sal
    FROM employees
    GROUP BY department
) AS dept_summary;

WITH HighEarners AS (
    SELECT id, name, salary FROM employees WHERE salary > 100000
)
SELECT COUNT(*) FROM HighEarners;

SELECT name, salary,
       (SELECT AVG(salary) FROM employees) AS overall_avg
FROM employees;

SELECT name, department, salary,
       RANK() OVER (PARTITION BY department ORDER BY salary DESC) as sal_rank
FROM employees;

WITH RECURSIVE NumberSequence AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM NumberSequence WHERE n < 5
)
SELECT * FROM NumberSequence;

START TRANSACTION;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 9999; -- non-existent
ROLLBACK;

START TRANSACTION;
INSERT INTO logs VALUES ('Step 1');
SAVEPOINT sp1;
INSERT INTO logs VALUES ('Step 2');
ROLLBACK TO sp1;
COMMIT;

CREATE TABLE products (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE orders (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    amount DECIMAL(10, 2)
);

